import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

/**
 * Where receipt bytes live. The database stores only the key. Production would implement this over object storage
 * (S3 etc.); the rest of the app doesn't change.
 */
export interface ReceiptStorage {
  save(key: string, data: Buffer): Promise<void>;
  /** Resolves null when the file is gone, so callers can answer 404 rather than 500. */
  read(key: string): Promise<Buffer | null>;
  remove(key: string): Promise<void>;
}

// Keys are generated by the server, but validate anyway: this is the last line of defence against path traversal.
const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

export class LocalDiskStorage implements ReceiptStorage {
  private readonly root: string;

  constructor(directory: string) {
    this.root = path.resolve(directory);
  }

  private resolve(key: string): string {
    if (!SAFE_KEY.test(key)) throw new Error(`Unsafe storage key: ${key}`);
    const full = path.join(this.root, key);
    if (path.dirname(full) !== this.root) throw new Error(`Storage key escapes the upload directory: ${key}`);
    return full;
  }

  async save(key: string, data: Buffer): Promise<void> {
    await mkdir(this.root, { recursive: true });
    await writeFile(this.resolve(key), data, { flag: 'wx' }); // 'wx': never overwrite an existing file
  }

  async read(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.resolve(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async remove(key: string): Promise<void> {
    await rm(this.resolve(key), { force: true });
  }
}
